#!/usr/bin/env python3
"""Offline finite-domain network rule mining service.

Reads exactly one JSON request on stdin and writes exactly one JSON response
on stdout.  See instruction.md for the full contract.
"""

import json
import math
import re
import sys

MAXBYTES = 8388608
MAXDEPTH = 64
I32MIN = -2147483648
I32MAX = 2147483647
SC = 840  # lcm(1..8): every value is carried exactly as 840 * true rational

NAME_RE = re.compile(r'[a-z][a-z0-9_]{0,31}')
TRACEID_RE = re.compile(r'[A-Za-z][A-Za-z0-9_-]{0,31}')
IDVAL_RE = re.compile(r'[A-Za-z0-9_.:-]{1,32}')
STR_RE = re.compile(r'"(?:[^"\\\x00-\x1f]|\\(?:["\\/bfnrt]|u[0-9A-Fa-f]{4}))*"', re.S)
BRACK_RE = re.compile(r'[\[\]{}]')

NUMERIC = ('TIME', 'SIZE', 'COUNT')
ALLTYPES = ('TIME', 'SIZE', 'COUNT', 'ID', 'FLAG')
CMPOPS = ('eq', 'ne', 'lt', 'le', 'gt', 'ge')
AGGOPS = ('sum', 'mean', 'min', 'max')
CMPSYM = {'eq': '==', 'ne': '!=', 'lt': '<', 'le': '<=', 'gt': '>', 'ge': '>='}
TOPKEYS = {'version', 'schema', 'window', 'atoms', 'policy',
           'train', 'probes', 'queries'}


class JsonErr(Exception):
    pass


class SchemaErr(Exception):
    pass


def is_int(x):
    return type(x) is int


def is_str(x):
    return type(x) is str


def is_list(x):
    return type(x) is list


def is_dict(x):
    return type(x) is dict


# ----------------------------------------------------------------------------
# JSON layer
# ----------------------------------------------------------------------------

def _hook(pairs):
    d = {}
    for k, v in pairs:
        if k in d:
            raise JsonErr('duplicate key')
        d[k] = v
    return d


def _pf(s):
    v = float(s)
    if not math.isfinite(v):
        raise JsonErr('nonfinite')
    return v


def _pc(_s):
    raise JsonErr('constant')


def json_depth(text):
    """Maximum container nesting depth (root container == 1)."""
    stripped = STR_RE.sub('""', text)
    depth = 0
    mx = 0
    for m in BRACK_RE.finditer(stripped):
        if m.group() == '[' or m.group() == '{':
            depth += 1
            if depth > mx:
                mx = depth
        else:
            depth -= 1
    return mx


def parse_json_text(text):
    try:
        obj = json.loads(text, object_pairs_hook=_hook, parse_float=_pf,
                         parse_constant=_pc)
    except JsonErr:
        raise
    except RecursionError:
        raise JsonErr('deep')
    except Exception:
        raise JsonErr('bad')
    if json_depth(text) > MAXDEPTH:
        raise JsonErr('depth')
    return obj


# ----------------------------------------------------------------------------
# AST validation / compilation
# ----------------------------------------------------------------------------

def compile_term(node, inq, K, fidx, counter):
    """Validate a term, return (type, depth, python expression string).

    Numeric values are represented exactly as SC * true value, so all
    arithmetic stays in exact integers (SC is divisible by every window
    length in 1..8).
    """
    if not is_dict(node):
        raise SchemaErr('term')
    ks = set(node)
    if ks == {'field', 'at'}:
        counter[0] += 1
        nm = node['field']
        if not is_str(nm) or nm not in fidx:
            raise SchemaErr('field')
        fi, fty = fidx[nm]
        at = node['at']
        if at == '$':
            if not inq:
                raise SchemaErr('dollar')
            idx = '_d'
        else:
            if not is_int(at) or not 0 <= at < K:
                raise SchemaErr('at')
            idx = str(at)
